  "avaliacoes": [
    {
      "id": "Eee9acdb502a647c4",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A fonte atribui à instalação a responsabilidade pela segurança das aeronaves que operam na zona de 500 metros e indica que devem existir procedimentos e meios para que operações de helideck, incluindo pouso, decolagem e abastecimento, ocorram sem riscos à saúde e à segurança na medida do razoavelmente praticável.",
          "trechos": [
            "Eee9acdb502a647c4:0:698",
            "Eee9acdb502a647c4:698:1398"
          ],
          "condicoes": [
            "guia de inspeção para operações de helideck",
            "jurisdição estrangeira identificada como UK"
          ],
          "limites": [
            "fonte estrangeira; não deve ser convertida em requisito brasileiro automático",
            "a formulação é geral e não detalha critérios de passageiros, manifestos ou POB"
          ]
        },
        {
          "proposicao": "A fonte indica a designação de uma pessoa competente como Helicopter Landing Officer (HLO), responsável pela gestão diária do helideck da instalação, pelo controle das operações associadas e pela supervisão da equipe do helideck.",
          "trechos": [
            "Eee9acdb502a647c4:698:1398"
          ],
          "condicoes": [
            "estrutura de gestão descrita pelo guia de inspeção"
          ],
          "limites": [
            "fonte estrangeira",
            "não traz equivalência brasileira de cargo nem matriz completa de competências"
          ]
        },
        {
          "proposicao": "Antes de operações de helicóptero, o helideck e a área ao redor devem ser verificados; detritos e itens soltos que possam ser arrastados pelo downwash devem ser removidos ou fixados, e a fonte também associa a prontidão de resposta à existência de plano de resposta para acidente no helideck e treinamento regular da equipe.",
          "trechos": [
            "Eee9acdb502a647c4:698:1398",
            "Eee9acdb502a647c4:1398:2098",
            "Eee9acdb502a647c4:2098:2190"
          ],
          "condicoes": [
            "fase prévia e concomitante às operações de helicóptero",
            "cada instalação pode ter práticas próprias"
          ],
          "limites": [
            "fonte estrangeira",
            "não define frequência exata de treinamentos nem parâmetros operacionais universais"
          ]
        }
      ]
    },
    {
      "id": "E5a772800367adc43",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte relata achados de inspeções baseadas em risco segundo os quais muitos operadores não conseguiram comprovar a realização regular de simulados de emergência médica, e recomenda incorporar treinamentos e exercícios regulares, com cenários realistas e análise crítica posterior para corrigir fraquezas e procedimentos inadequados.",
          "trechos": [
            "E5a772800367adc43:0:699",
            "E5a772800367adc43:1392:2085"
          ],
          "condicoes": [
            "alerta de segurança emitido por órgão estrangeiro após inspeções",
            "voltado a preparação para emergência médica em instalações offshore"
          ],
          "limites": [
            "recomendação e relato de inspeção, não norma brasileira",
            "não especifica periodicidade aplicável de forma universal neste corpus"
          ]
        },
        {
          "proposicao": "A fonte informa que em algumas instalações macas Stokes estavam inoperantes, mal localizadas, inadequadas para içamento ou raramente incluídas em exercícios, e recomenda sua inspeção quanto à capacidade segura de içamento e sua inclusão em simulados.",
          "trechos": [
            "E5a772800367adc43:0:699",
            "E5a772800367adc43:2085:2429"
          ],
          "condicoes": [
            "contexto de resposta a evacuação e transporte de pessoas em emergência"
          ],
          "limites": [
            "recomendação de autoridade estrangeira",
            "não estabelece requisito brasileiro nem garante suficiência para todos os cenários de evacuação médica"
          ]
        },
        {
          "proposicao": "A fonte registra que alguns helidecks apresentavam detritos, corrosão e preocupações com capacidade de carga, e que alguns eram pequenos demais para pouso de helicópteros SAR S-61, indicando que características físicas e condições do helideck podem limitar a compatibilidade com determinados meios de resgate.",
          "trechos": [
            "E5a772800367adc43:699:1392"
          ],
          "condicoes": [
            "achados observados em parte das instalações inspecionadas"
          ],
          "limites": [
            "resultado observacional em instalações inspecionadas por órgão estrangeiro",
            "não define critérios dimensionais gerais nem pode ser generalizado para todos os helidecks offshore"
          ]
        }
      ]
    },
    {
      "id": "E33187dbc0a59079f",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte recomenda monitorar perigos durante todas as fases das operações com helicóptero, incluindo a suspensão de movimentos de guindaste, com tempo e espaço suficientes para manobra segura.",
          "trechos": [
            "E33187dbc0a59079f:0:698",
            "E33187dbc0a59079f:2090:2434"
          ],
          "condicoes": [
            "operações de helideck com atividades simultâneas próximas",
            "alerta de segurança de órgão estrangeiro"
          ],
          "limites": [
            "recomendação estrangeira",
            "a referência normativa citada é externa e não deve ser tratada como requisito brasileiro automático"
          ]
        },
        {
          "proposicao": "A fonte recomenda manter comunicação aberta e contínua com o pessoal da instalação para coordenar atividades, confirmar informações críticas e divulgar atualizações de status do helideck e de operações simultâneas.",
          "trechos": [
            "E33187dbc0a59079f:0:698",
            "E33187dbc0a59079f:698:1397"
          ],
          "condicoes": [
            "coordenação operacional entre equipes envolvidas em helideck e demais atividades"
          ],
          "limites": [
            "recomendação estrangeira de caráter geral",
            "não detalha protocolos documentais, manifestos ou controle de POB"
          ]
        },
        {
          "proposicao": "A fonte recomenda verificações obrigatórias das condições do helideck e das operações próximas antes da atividade aérea, além de treinamento frequente e auditorias rotineiras para manter protocolos atualizados.",
          "trechos": [
            "E33187dbc0a59079f:0:698",
            "E33187dbc0a59079f:698:1397"
          ],
          "condicoes": [
            "antes da atividade de voo e na gestão contínua da operação"
          ],
          "limites": [
            "recomendação estrangeira",
            "não informa critérios mínimos objetivos de auditoria, aceitação ou frequência"
          ]
        }
      ]
    },
    {
