      "achados": [
        {
          "proposicao": "A fonte compilada menciona receio quanto ao transporte por helicópteros como fator psicossocial em estudos offshore, mas não desenvolve critérios operacionais de voos, helideck, manifestos, POB, competências ou evacuação médica para o recorte.",
          "trechos": [
