          ]
        },
        {
          "proposicao": "A ANP observou que o operador da instalação não havia avaliado cenário de redução de POB nos estudos de risco previamente à contingência e tampouco havia utilizado gestão de mudanças quando gerente de plataforma, coordenadores ou supervisores atuavam também como operadores.",
          "trechos": [
            "E583442bf19576951:700:1396"
          ],
          "condicoes": [
            "instalações de produção auditadas",
            "análise de estudos de risco e contingência"
          ],
          "limites": [
            "resultado de auditoria em contexto específico",
            "o trecho não informa metodologia de avaliação de POB nem critérios quantitativos"
          ]
        }
